sys_script_client.script:
function onChange(control, oldValue, newValue, isLoading, isTemplate) {

    if (isLoading) {
        return;
    }

    if (!newValue) {
        g_form.setValue('total_count', '0');
        return;
    }

    var driveSysId = g_form.getUniqueValue();

    if (!driveSysId) {
        g_form.setValue('total_count', '0');
        return;
    }

    var ga = new GlideAjax('x_snc_college_pl_0.PlacementStatisticsService');

    ga.addParam('sysparm_name', 'getCount');
    ga.addParam('sysparm_status', newValue);
    ga.addParam('sysparm_drive', driveSysId);

    ga.getXMLAnswer(function(answer) {
        g_form.setValue('total_count', answer || '0');
    });
}
